content.content:
1	// The setup card: what this chat asked the setup to be, the settings actually
2	// in force on the plate, and what the slice says it will cost. The anatomy is
3	// the Figma "Current Setup Card" page, sections 5 to 7; the facts come from
4	// OrcaSlicer through WorkspaceContext, never from the conversation.
5	//
6	// The card's states are combinations of independent facts, not separate
7	// cards: whose chat it is (live or saved), where the setup came from, what
8	// the agent is doing, and what the estimate is worth. Every row has its own
9	// presence rule and every fallback ends in an honest sentence or in omitting
10	// the row -- never a zero, a guess, or today's value under a saved heading.
11	
12	import { ReactNode, useState } from 'react';
13	import { AppliedSetupInfo, ChangeInfo, PresetDeltaInfo, SetupIdentityInfo, SliceEstimateInfo,
14	  WorkspaceContext } from '../bridge/protocol';
15	
16	export interface SetupCardProps {
17	  context: WorkspaceContext | null;
18	  expanded: boolean;
19	  onToggle: () => void;
20	  // The agent is mid-turn. The card keeps showing what is confirmed.
21	  working?: boolean;
22	  // An earlier chat's saved summary: nothing here follows the live project.
23	  historical?: boolean;
24	  savedAt?: string;
25	  // False when no agent is configured: the card is then a label for the
26	  // selected preset and claims nothing more.
27	  agentAvailable?: boolean;
28	  // This chat's change log, oldest first. It is the only source of who
29	  // changed what, so without it the card says nothing about authorship.
30	  changes?: ChangeInfo[];
31	  // The clock the "just changed" window is measured against.
32	  now?: number;
33	  // The plate's last current estimate before the newest change, when the
34	  // caller saw one; pairs with the estimate now in force.
35	  estimateBefore?: SliceEstimateInfo | null;
36	  // The send this saved summary belongs to, when the chat sliced and sent.
37	  sent?: { at: string; printer: string };
38	  // Findings another deterministic check produced, shown after the printer
39	  // comparison's own. Never a model's opinion or an unanswered question.
40	  attention?: Finding[];
41	  onCompute?: () => void;
42	  onUndo?: (changeSeq: number) => void;
43	}
44	
45	type Setting = AppliedSetupInfo['settings'][number];
46	type LocalOverride = AppliedSetupInfo['localOverrides'][number];
47	
48	// "~2h 18m" over an hour, "~42 min" under it. Seconds are never shown: the
49	// number is an estimate and false precision reads as a promise.
50	export function formatPrintTime(seconds: number): string {
51	  const minutes = Math.round(seconds / 60);
52	  if (minutes < 60) return `~${minutes} min`;
53	  return `~${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
54	}
55	
56	export function formatGrams(grams: number): string {
57	  return `${grams < 10 ? Math.round(grams * 10) / 10 : Math.round(grams)} g`;
58	}
59	
60	// OrcaSlicer has no currency concept -- filament_cost's unit is literally
61	// "money/kg" -- so the host reads the ISO code from the machine's regional
62	// settings and the page formats it the way that viewer's locale writes money.
63	// Without a code there is nothing to denominate the number in, so it carries
64	// the word "cost" the way the slicer's own G-code legend does.
65	export function formatCost(cost: number, currency: string): string {
66	  if (currency) {
67	    try {
68	      return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(cost);
69	    } catch {
70	      // An unknown code is not worth losing the number over.
71	    }
72	  }
73	  return `cost ${cost.toFixed(2)}`;
74	}
75	
76	// "Oct 3, 10:42". A value that is not a timestamp is shown as it came.
77	export function formatMoment(value: string | undefined): string {
78	  if (!value) return '';
79	  const date = new Date(value);
80	  if (Number.isNaN(date.getTime())) return value;
81	  return date.toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false });
82	}
83	
84	// How long a completed agent change is "just changed".
85	export const RECENT_CHANGE_MS = 60000;
86	
87	// Display names for the stable config keys a local override may carry. Only
88	// these are listed by name; anything else is counted, not described.
89	const SETTING_NAMES: Record<string, string> = {
90	  layer_height: 'Layer height',
91	  wall_loops: 'Wall loops',
92	  sparse_infill_density: 'Sparse infill',
93	  sparse_infill_pattern: 'Infill pattern',
94	  enable_support: 'Supports',
95	  support_type: 'Support type',
96	  support_on_build_plate_only: 'Supports from build plate only',
97	  top_shell_layers: 'Top shell layers',
98	  bottom_shell_layers: 'Bottom shell layers',
99	  top_shell_thickness: 'Top minimum thickness',
100	  bottom_shell_thickness: 'Bottom minimum thickness',
101	  brim_type: 'Brim type',
102	  brim_width: 'Brim width',
103	  extruder: 'Filament',
104	};
105	
106	
107	const on = (value: string) => value === '1' || value === 'true';
108	const sentence = (text: string) => text.charAt(0).toUpperCase() + text.slice(1);
109	const plural = (count: number, one: string, many: string) => `${count} ${count === 1 ? one : many}`;
110	
111	function millimetres(value: string): string {
112	  const number = Number(value);
113	  return Number.isFinite(number) ? `${number.toFixed(2)} mm` : `${value} mm`;
114	}
115	
116	// An enum's stable value, readable: "adaptive_cubic" is "adaptive cubic".
117	const enumWord = (value: string) => value.replace(/[_-]+/g, ' ').trim();
118	
119	// A modifier is "bracket.stl / Mounting tabs"; inside its own object's
120	// section the volume's name is enough.
121	const shortTarget = (target: string) => target.includes(' / ') ? target.slice(target.indexOf(' / ') + 3) : target;
122	
123	function settingOf(setup: AppliedSetupInfo, key: string): Setting | undefined {
124	  return setup.settings.find((setting) => setting.key === key);
125	}
126	
127	// The overrides somewhere inside an object -- a modifier, a part, a height
128	// range -- that set this key. An object's own value is not one of them: it is
129	// already the value the object's scope reports.
130	function exceptions(setup: AppliedSetupInfo, key: string): LocalOverride[] {
131	  return setup.localOverrides.filter((local) => local.kind !== 'object' && local.key === key);
132	}
133	
134	function wallsText(value: string): string { return `${value} ${value === '1' ? 'wall' : 'walls'}`; }
135	
136	function infillText(density: string, pattern: string | undefined): string {
137	  const percent = Number.parseFloat(density);
138	  if (percent === 0) return 'no sparse infill';
139	  // Fully dense is not printed in the sparse pattern, so the pattern goes.
140	  if (percent === 100) return '100% infill';
141	  return `${density}${pattern ? ` ${enumWord(pattern)}` : ''} infill`;
142	}
143	
144	function supportsText(enabled: string, type: string | undefined, plateOnly: string | undefined): string {
145	  if (!on(enabled)) return 'supports off';
146	  const tree = !!type && type.startsWith('tree');
147	  if (plateOnly && on(plateOnly)) return `${tree ? 'tree supports' : 'supports'} from build plate`;
148	  return tree ? 'tree supports' : 'supports on';
149	}
150	
151	// One summary clause for one fact. A value is stated outright only when it
152	// holds for the whole plate; a single named exception is quoted, and anything
153	// more involved is pointed at rather than approximated.
154	function clause(setup: AppliedSetupInfo, setting: Setting | undefined, text: (value: string) => string,
155	  exception: (value: string) => string, varies: string, local: string): string {
156	  if (!setting || setting.coverage === 'unavailable') return '';
157	  if (setting.coverage === 'exact') return text(setting.value);
158	  if (setting.coverage === 'mixed') return varies;
159	  const found = exceptions(setup, setting.key);
160	  const quotable = found.length === 1 && (found[0].kind === 'modifier' || found[0].kind === 'part') && found[0].value;
161	  return quotable ? `${text(setting.value)}; ${shortTarget(found[0].target)}: ${exception(found[0].value)}` : local;
162	}
163	
164	// The objects whose settings are not simply the plate's: an object-level
165	// value that differs from the plate default, or any customization inside it.
166	function objectsThatDiffer(setup: AppliedSetupInfo): number {
167	  const differing = new Set<number>();
168	  for (const setting of setup.settings)
169	    for (const scope of setting.scopes)
170	      if (scope.object !== undefined && setting.base !== undefined && scope.value !== setting.base) differing.add(scope.object);
171	  for (const local of setup.localOverrides)
172	    if (local.object !== undefined && (local.kind !== 'object' || !local.key)) differing.add(local.object);
173	  return differing.size;
174	}
175	
176	// The two summary lines: layer height and walls, then infill and supports.
177	// The order is fixed; it never follows whichever setting changed last.
178	export function appliedSummary(setup: AppliedSetupInfo | null | undefined): string[] {
179	  if (!setup || setup.printableObjects === 0) return [];
180	  // A vase has one spiralling wall and no infill, whatever the keys say.
181	  if (setup.spiralMode) return ['Spiral vase mode'];
182	  const layer = settingOf(setup, 'layer_height');
183	  const walls = settingOf(setup, 'wall_loops');
184	  const density = settingOf(setup, 'sparse_infill_density');
185	  const pattern = settingOf(setup, 'sparse_infill_pattern');
186	  const enabled = settingOf(setup, 'enable_support');
187	  const type = settingOf(setup, 'support_type');
188	  const plateOnly = settingOf(setup, 'support_on_build_plate_only');
189	  const exactValue = (setting: Setting | undefined) => setting?.coverage === 'exact' ? setting.value : undefined;
190	
191	  // Objects disagree: no value is the plate's, so the lines state the plate
192	  // default as a default and count the objects that depart from it.
193	  const disagree = [layer, walls, density, enabled].some((setting) => setting?.coverage === 'mixed');
194	  if (disagree && layer?.base && walls?.base && density?.base) {
195	    const height = setup.variableLayerHeight ? 'variable layer height' : `${millimetres(layer.base)} layers`;
196	    return [
197	      `Plate default: ${height} · ${wallsText(walls.base)}`,
198	      `${sentence(infillText(density.base, pattern?.base))} · ${
199	        plural(objectsThatDiffer(setup), 'object', 'objects')} with local overrides`,
200	    ];
201	  }
202	
203	  const layerClause = setup.variableLayerHeight ? 'variable layer height' :
204	    clause(setup, layer, (value) => `${millimetres(value)} layers`, millimetres,
205	      'layer height varies by object', 'local layer heights — see details');
206	  const wallClause = clause(setup, walls, wallsText, (value) => value,
207	    'walls vary by object', 'local wall settings — see details');
208	  const infillClause = clause(setup, density, (value) => infillText(value, exactValue(pattern)), (value) => value,
209	    'infill varies by object', 'local infill settings — see details');
210	  let supportClause = '';
211	  if (enabled && enabled.coverage !== 'unavailable') {
212	    if (enabled.coverage === 'mixed') supportClause = 'supports vary by object';
213	    else {
214	      supportClause = supportsText(enabled.value, exactValue(type), exactValue(plateOnly));
215	      // Blockers, enforcers, paint, or a modifier's own support keys: the
216	      // configured mode is still true, and it is not the whole story.
217	      if (enabled.coverage === 'local') supportClause += '; local support edits';
218	    }
219	  }
220	  return [[layerClause, wallClause], [infillClause, supportClause]]
221	    .map((parts) => parts.filter(Boolean).join(' · ')).filter(Boolean).map(sentence);
222	}
223	
224	// What the estimate area says. Time and material always belong to the same
225	// plate and the same slice; neither is shown as zero when it is missing.
226	export interface EstimateView {
227	  heading: string;
228	  metrics: { icon: string; text: string }[];
229	  cost: string;
230	  plate: string;
231	  description: string;
232	  status: 'current' | 'recomputing' | 'stale' | 'none';
233	  sliced: boolean;
234	}
235	
236	export function estimateView(context: WorkspaceContext): EstimateView {
237	  const plate = context.plates.find((item) => item.active);
238	  const view: EstimateView = { heading: '', metrics: [], cost: '', plate: plate?.name ?? '', description: '',
239	    status: 'none', sliced: !!plate?.sliced };
240	  if (!plate) return { ...view, description: 'Estimate unavailable' };
241	  const estimate = plate.estimate;
242	  const scoped = (text: string) => plate.name ? `${text} · ${plate.name}` : text;
243	  // A host that predates the two availability flags sent a zero for a
244	  // quantity it could not work out, so there a zero means absent.
245	  const metrics: EstimateView['metrics'] = [];
246	  if (estimate && (estimate.timeAvailable ?? estimate.printTimeSeconds > 0))
247	    metrics.push({ icon: 'clock', text: formatPrintTime(estimate.printTimeSeconds) });
248	  if (estimate && (estimate.materialAvailable ?? estimate.materialGrams > 0))
249	    metrics.push({ icon: 'package', text: formatGrams(estimate.materialGrams) });
250	  if (plate.estimateStatus === 'recomputing')
251	    return { ...view, status: 'recomputing', heading: 'Time & material estimates recomputing…',
252	      description: scoped('Settings confirmed') };
253	  if (metrics.length === 0)
254	    return { ...view, description: scoped(plate.sliced ? 'Estimate unavailable' : 'Not sliced yet · estimates unavailable') };
255	  // A priced job so small it rounds to nothing reads exactly like the
256	  // unpriced case, so it takes the same exit: no clause rather than 0.00.
257	  const cost = estimate && estimate.materialCost !== null && estimate.materialCost >= 0.005
258	    ? formatCost(estimate.materialCost, context.currency) : '';
259	  if (plate.estimateStatus === 'stale')
260	    return { ...view, status: 'stale', heading: 'Previous estimates · not current', metrics, cost };
261	  return { ...view, status: 'current', metrics, cost };
262	}
263	
264	// One deterministic finding. A check that has only its headline to offer is
265	// one row; one that compared two values can also show them.
266	export interface Finding { title: string; detail?: string; facts?: string[]; }
267	
268	// Findings a deterministic comparison produced, most consequential first.
269	// The printer's side is what it last reported, with when: nothing here can
270	// prove what is loaded this second, and a mismatch nobody timed is not shown.
271	export function deterministicAttention(context: WorkspaceContext): Finding[] {
272	  const review = context.printerReview;
273	  if (!review) return [];
274	  const priority: Record<string, number> = { filament: 0, nozzle: 1, model: 2, plate: 3 };
275	  const noun: Record<string, string> = { filament: 'material', nozzle: 'nozzle', model: 'printer', plate: 'build plate' };
276	  const when = formatMoment(review.observed?.observedAt);
277	  return [...review.mismatches].sort((a, b) => (priority[a.what] ?? 4) - (priority[b.what] ?? 4)).flatMap((mismatch) => {
278	    const thing = noun[mismatch.what] ?? 'printer setup';
279	    if (mismatch.source === 'device') {
280	      if (!when) return [];
281	      const facts = [`Setup: ${mismatch.configured}`, `Printer last reported: ${mismatch.observed}`, `Reported ${when}`];
282	      if (review.observed?.connection) facts.push(`Printer is ${review.observed.connection} now`);
283	      return [{ title: `Last reported ${thing} differs`,
284	        detail: `Setup uses ${mismatch.configured}. Printer last reported ${mismatch.observed}.`, facts }];
285	    }
286	    return [{ title: `Confirmed ${thing} differs`,
287	      detail: `Setup uses ${mismatch.configured}. You confirmed ${mismatch.observed}.`,
288	      facts: [`Setup: ${mismatch.configured}`, `You confirmed: ${mismatch.observed}`] }];
289	  });
290	}
291	
292	// The newest thing in the log, when it is a change the agent just completed:
293	// every entry it made since the same point in the conversation.
294	export function recentAgentChange(changes: ChangeInfo[] | undefined, now: number): ChangeInfo[] {
295	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
296	  const last = log[log.length - 1];
297	  if (!last || last.actor !== 'agent' || (last.kind !== 'setting' && last.kind !== 'step')) return [];
298	  const made = Date.parse(last.createdAt);
299	  if (!Number.isFinite(made) || now - made >= RECENT_CHANGE_MS || now < made) return [];
300	  let start = log.length - 1;
301	  while (start > 0 && log[start - 1].actor === 'agent' && log[start - 1].afterId === last.afterId &&
302	    (log[start - 1].kind === 'setting' || log[start - 1].kind === 'step')) start -= 1;
303	  return log.slice(start);
304	}
305	
306	// The settings the person changed by hand since the agent last changed
307	// anything, net of their own later edits to the same setting. Restoring a
308	// saved project replays its settings and logs them under the person who asked
309	// for the restore; those are the restore's work, not hand edits, so the run
310	// starts after the newest restore.
311	export function handEdits(changes: ChangeInfo[] | undefined): ChangeInfo[] {
312	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
313	  let start = log.length;
314	  while (start > 0 && log[start - 1].actor === 'person' && log[start - 1].kind !== 'restore') start -= 1;
315	  const net = new Map<string, ChangeInfo>();
316	  for (const change of log.slice(start))
317	    if (change.kind === 'setting') net.set(change.label, change);
318	  return [...net.values()];
319	}
320	
321	function changeText(change: ChangeInfo): string {
322	  if (change.kind !== 'setting') return change.label || 'Object settings changed';
323	  return `${change.label} ${change.from || 'none'} → ${change.to || 'none'}`;
324	}
325	
326	function estimatePair(estimate: SliceEstimateInfo): string {
327	  return `${formatPrintTime(estimate.printTimeSeconds)} / ${formatGrams(estimate.materialGrams)}`;
328	}
329	
330	function Row({ label, children }: { label: string; children: ReactNode }) {
331	  return <div className="current-setup-row"><dt>{label}</dt><dd>{children}</dd></div>;
332	}
333	
334	function Identity({ identity }: { identity: SetupIdentityInfo | null | undefined }) {
335	  if (!identity) return <p className="current-setup-note">Printer and material details unavailable</p>;
336	  const several = identity.filaments.length > 1;
337	  return <dl className="current-setup-rows">
338	    {identity.printer && <Row label="Printer">{identity.printer}</Row>}
339	    {identity.nozzles.length > 0 && <Row label={identity.nozzles.length > 1 ? 'Nozzles' : 'Nozzle'}>
340	      {identity.nozzles.map((size) => `${size} mm`).join(', ')}</Row>}
341	    {identity.filaments.map((filament, index) => <Row key={index} label={several ? `Filament ${index + 1}` : 'Filament'}>
342	      {filament.preset || filament.material || 'Unavailable'}</Row>)}
343	    {identity.plateType && <Row label="Build plate">{identity.plateType}</Row>}
344	  </dl>;
345	}
346	
347	// Objects disagree. The plate's own value is still a fact worth showing, as
348	// long as it is not shown alone.
349	function varies(setting: Setting | undefined, exact: (value: string) => string): string {
350	  return setting?.base ? `${exact(setting.base)} · varies by object` : 'Varies by object';
351	}
352	
353	// One applied-settings row's value. Off, mixed, and unknown each read
354	// differently: they are three different facts.
355	function generic(setting: Setting | undefined, exact: (value: string) => string): string {
356	  if (!setting || setting.coverage === 'unavailable') return 'Unavailable';
357	  if (setting.coverage === 'mixed') return varies(setting, exact);
358	  if (setting.coverage === 'local') return 'Local settings';
359	  return exact(setting.value);
360	}
361	
362	function appliedRows(setup: AppliedSetupInfo): { label: string; value: string }[] {
363	  const get = (key: string) => settingOf(setup, key);
364	  const exactValue = (key: string) => get(key)?.coverage === 'exact' ? get(key)!.value : undefined;
365	  const rows: { label: string; value: string }[] = [];
366	  rows.push({ label: 'Layer height', value: setup.variableLayerHeight ? 'Variable' :
367	    clause(setup, get('layer_height'), millimetres, millimetres, varies(get('layer_height'), millimetres), 'Local settings') || 'Unavailable' });
368	  if (setup.spiralMode) {
369	    rows.push({ label: 'Mode', value: 'Spiral vase' });
370	  } else {
371	    rows.push({ label: 'Wall loops', value:
372	      clause(setup, get('wall_loops'), (value) => value, (value) => value, varies(get('wall_loops'), (value) => value),
373	        'Local settings') || 'Unavailable' });
374	    const infill = (value: string) => {
375	      const percent = Number.parseFloat(value);
376	      if (percent === 0) return 'None';
377	      if (percent === 100) return '100%';
378	      const pattern = exactValue('sparse_infill_pattern');
379	      return pattern ? `${value} · ${enumWord(pattern)}` : value;
380	    };
381	    rows.push({ label: 'Infill', value: clause(setup, get('sparse_infill_density'), infill, (value) => value,
382	      varies(get('sparse_infill_density'), infill), 'Local settings') || 'Unavailable' });
383	    const top = get('top_shell_layers');
384	    const bottom = get('bottom_shell_layers');
385	    if (top || bottom) {
386	      const layers = top?.coverage === 'exact' && bottom?.coverage === 'exact'
387	        ? `${top.value} / ${bottom.value} layers` : generic(top?.coverage === 'exact' ? bottom : top, (value) => value);
388	      // A minimum thickness can add shells beyond the count, so when one is
389	      // set the count alone does not describe the shell.
390	      const minimum = [exactValue('top_shell_thickness'), exactValue('bottom_shell_thickness')];
391	      const constrained = layers.endsWith('layers') && minimum.every((value) => value !== undefined) &&
392	        minimum.some((value) => Number(value) > 0);
393	      rows.push({ label: 'Top / bottom', value: constrained
394	        ? `${layers} · min ${Number(minimum[0])} / ${Number(minimum[1])} mm` : layers });
395	    }
396	  }
397	  const enabled = get('enable_support');
398	  const supportMode = (value: string) => {
399	    if (!on(value)) return 'Off';
400	    const type = exactValue('support_type') ?? '';
401	    const kind = `${type.startsWith('tree') ? 'Tree' : 'Normal'}${type.endsWith('(manual)') ? ' (manual)' : ''}`;
402	    return on(exactValue('support_on_build_plate_only') ?? '') ? `${kind} · build plate only` : kind;
403	  };
404	  // Blockers, enforcers and paint leave the configured mode true and
405	  // incomplete, so the row says both.
406	  const supports = enabled?.coverage === 'local' ? `${supportMode(enabled.value)}; local support edits`
407	    : generic(enabled, supportMode);
408	  rows.push({ label: 'Supports', value: supports });
409	  const brim = get('brim_type');
410	  if (brim) rows.push({ label: 'Brim', value: generic(brim, (value) => {
411	    const width = exactValue('brim_width');
412	    const sized = (where: string) => width && Number(width) > 0 ? `${Number(width)} mm ${where}` : sentence(where);
413	    switch (value) {
414	      case 'no_brim': return 'None';
415	      case 'auto_brim': return 'Auto';
416	      case 'outer_only': return sized('outer brim');
417	      case 'inner_only': return sized('inner brim');
418	      case 'outer_and_inner': return sized('outer and inner brim');
419	      case 'brim_ears': return 'Mouse ears';
420	      default: return sentence(enumWord(value));
421	    }
422	  }) });
423	  return rows;
424	}
425	
426	function overrideValue(local: LocalOverride, identity: SetupIdentityInfo | null | undefined): string {
427	  if (local.key === 'extruder') {
428	    const index = Number(local.value);
429	    const filament = Number.isInteger(index) && index > 0 ? identity?.filaments[index - 1] : undefined;
430	    return filament ? `${index} · ${filament.preset || filament.material}` : local.value;
431	  }
432	  if (local.key === 'layer_height' || local.key.endsWith('_thickness')) return local.value ? millimetres(local.value) : 'variable';
433	  if (local.key === 'enable_support' || local.key === 'support_on_build_plate_only') return on(local.value) ? 'on' : 'off';
434	  return enumWord(local.value);
435	}
436	
437	// One object's customizations, its own values first: what each is on, and
438	// what it sets. A value is the one configured on that owner; where the owner
439	// reaches in the print is the slicer's business and is not claimed here.
440	function overrideEntries(setup: AppliedSetupInfo, locals: LocalOverride[], identity: SetupIdentityInfo | null | undefined,
441	  compare: boolean): { head: string; body: string }[] {
442	  const describe = (local: LocalOverride) => `${SETTING_NAMES[local.key].toLowerCase()} ${overrideValue(local, identity)}`;
443	  const own = locals.filter((local) => local.kind === 'object' && local.key);
444	  const entries = own.length > 0 ? [{ head: 'Object override', body: own.map(describe).join(', ') }] : [];
445	  const inside = new Map<string, LocalOverride[]>();
446	  for (const local of locals.filter((item) => item.kind !== 'object' || !item.key)) {
447	    const name = `${shortTarget(local.target)}\u0000${local.kind}`;
448	    inside.set(name, [...(inside.get(name) ?? []), local]);
449	  }
450	  for (const [name, group] of inside) {
451	    const [target, kind] = name.split('\u0000');
452	    const keyed = group.filter((local) => local.key && local.value);
453	    if (keyed.length === 0) { entries.push({ head: target, body: kind }); continue; }
454	    entries.push({ head: `${target} (${kind})`, body: keyed.map((local) => {
455	      // Beside a modifier's value, the object's own: the comparison a
456	      // reader is making.
457	      const rest = compare ? settingOf(setup, local.key)?.scopes.find((scope) => scope.object === local.object)?.value : undefined;
458	      return rest === undefined ? describe(local)
459	        : `${describe(local)} · rest of object: ${overrideValue({ ...local, value: rest }, identity)}`;
460	    }).join(', ') });
461	  }
462	  return entries;
463	}
464	
465	function LocalOverrides({ setup, identity }: { setup: AppliedSetupInfo; identity: SetupIdentityInfo | null | undefined }) {
466	  // A setting the card has no name for is counted, never described: the
467	  // list says what was configured, and it does not pretend to be every key.
468	  const named = setup.localOverrides.filter((local) => !local.key || SETTING_NAMES[local.key]);
469	  const unnamed = setup.localOverrides.length - named.length;
470	  const names = setup.objects ?? [];
471	  const objectValue = (key: string, object: number) =>
472	    settingOf(setup, key)?.scopes.find((scope) => scope.object === object)?.value;
473	  const other = unnamed > 0 && <p className="current-setup-note">{plural(unnamed, 'other local setting', 'other local settings')}</p>;
474	  if (names.length > 1) {
475	    return <section className="current-setup-section">
476	      <h3>Local overrides · {names.length} objects</h3>
477	      {names.map((name, object) => {
478	        const entries = overrideEntries(setup, named.filter((local) => local.object === object), identity, false);
479	        const walls = objectValue('wall_loops', object);
480	        const density = objectValue('sparse_infill_density', object);
481	        const values = setup.spiralMode ? [] : [walls && wallsText(walls),
482	          density && infillText(density, objectValue('sparse_infill_pattern', object)).replace(/ infill$/, '')].filter(Boolean);
483	        return <div className="current-setup-object" key={object}>
484	          <p className="current-setup-object-name">{name}</p>
485	          {values.length > 0 && <p className="current-setup-object-values">{values.join(' · ')}</p>}
486	          <p className="current-setup-note">{entries.length > 0
487	            ? entries.map((entry) => `${entry.head}: ${entry.body}`).join(' · ') : 'No local overrides · uses plate settings'}</p>
488	        </div>;
489	      })}
490	      {other}
491	    </section>;
492	  }
493	  const entries = overrideEntries(setup, named, identity, true);
494	  return <section className="current-setup-section">
495	    <h3>{names.length === 1 ? `Local overrides · ${names[0]}` : 'Local overrides'}</h3>
496	    {entries.length === 0 && unnamed === 0 && <p className="current-setup-note">No local overrides found</p>}
497	    {entries.map((entry, index) => <div className="current-setup-override" key={index}>
498	      <p className="current-setup-override-target">{entry.head}</p>
499	      <p className="current-setup-note">{sentence(entry.body)}</p>
500	    </div>)}
501	    {other}
502	  </section>;
503	}
504	
505	function PresetChanges({ deltas }: { deltas: PresetDeltaInfo[] }) {
506	  const [open, setOpen] = useState(false);
507	  // The count is the rows the list shows: one per setting, never a group.
508	  return <>
509	    <button type="button" className="current-setup-disclosure" aria-expanded={open} onClick={() => setOpen(!open)}>
510	      <span className={`jp-icon jp-icon-chevron-${open ? 'down' : 'right'}`} aria-hidden="true" />
511	      {plural(deltas.length, 'change', 'changes')} from preset
512	    </button>
513	    {open && <dl className="current-setup-rows" data-testid="setup-preset-changes">
514	      {deltas.map((delta) => <Row key={delta.key} label={delta.label || delta.key}>{delta.preset} → {delta.value}</Row>)}
515	    </dl>}
516	  </>;
517	}
518	
519	function Details({ context }: { context: WorkspaceContext }) {
520	  const setup = context.appliedSetup;
521	  const plate = context.plates.find((item) => item.active);
522	  return <div className="current-setup-details" data-testid="current-setup-expansion">
523	    <hr className="current-setup-divider" />
524	    <section className="current-setup-section">
525	      <h3>Printer &amp; material</h3>
526	      <Identity identity={context.setupIdentity} />
527	    </section>
528	    <hr className="current-setup-divider" />
529	    <section className="current-setup-section">
530	      <h3>Applied settings{plate?.name ? ` · ${plate.name}` : ''}</h3>
531	      {setup ? <dl className="current-setup-rows">
532	        {appliedRows(setup).map((row) => <Row key={row.label} label={row.label}>{row.value}</Row>)}
533	      </dl> : <p className="current-setup-note">Applied setting details are unavailable for this setup.</p>}
534	    </section>
535	    <hr className="current-setup-divider" />
536	    {setup ? <LocalOverrides setup={setup} identity={context.setupIdentity} /> : <section className="current-setup-section">
537	      <h3>Local overrides</h3>
538	      <p className="current-setup-note">Local override details unavailable</p>
539	    </section>}
540	    <hr className="current-setup-divider" />
541	    <dl className="current-setup-rows"><Row label="Base preset">{context.printer.process || 'Unavailable'}</Row></dl>
542	    {context.presetDeltas.length > 0 && <>
543	      <hr className="current-setup-divider" />
544	      <PresetChanges deltas={context.presetDeltas} />
545	    </>}
546	  </div>;
547	}
548	
549	function Metrics({ estimate }: { estimate: EstimateView }) {
550	  return <div className="current-setup-metrics">
551	    {estimate.metrics.map((metric) => <span className="current-setup-metric" key={metric.icon}>
552	      <span className={`jp-icon jp-icon-${metric.icon}`} aria-hidden="true" />{metric.text}</span>)}
553	    {estimate.plate && <span className="current-setup-metric">
554	      <span className="jp-icon jp-icon-grid-3x3" aria-hidden="true" />{estimate.plate}</span>}
555	    {estimate.cost && <span className="current-setup-metric">{estimate.cost}</span>}
556	  </div>;
557	}
558	
559	function Attention({ findings }: { findings: Finding[] }) {
560	  const [open, setOpen] = useState(false);
561	  if (findings.length === 0) return null;
562	  const first = findings[0];
563	  // More than one finding, or one with compared values, has something to open.
564	  const reviewable = findings.length > 1 || (first.facts ?? []).length > 0;
565	  const subject = findings.length > 1 ? plural(findings.length, 'finding', 'findings') : first.title.replace(/^(Last reported|Confirmed) | differs$/g, '');
566	  return <>
567	    <div className="current-setup-attention">
568	      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />{first.title}</p>
569	      {first.detail && <p className="current-setup-line">{first.detail}</p>}
570	      {/* Reviewing shows what was compared. It changes nothing on the
571	          printer or in the setup. */}
572	      {reviewable && <button type="button" className="current-setup-link" aria-expanded={open} onClick={() => setOpen(!open)}>
573	        Review {subject}</button>}
574	      {open && <ul className="current-setup-findings">
575	        {findings.map((finding, index) => <li key={index}>
576	          {findings.length > 1 && <strong>{finding.title}</strong>}
577	          {(finding.facts ?? []).map((fact) => <span key={fact}>{fact}</span>)}
578	        </li>)}
579	      </ul>}
580	    </div>
581	    <hr className="current-setup-divider" />
582	  </>;
583	}
584	
585	export function SetupCard({ context, expanded, onToggle, working: busy = false, historical = false, savedAt,
586	  agentAvailable = true, changes, now = Date.now(), estimateBefore, sent, attention = [], onCompute, onUndo }: SetupCardProps) {
587	  if (!context) return null;
588	  // Conversation status outranks live activity: a saved card is never
589	  // working, whatever the chat that is active happens to be doing.
590	  const working = busy && !historical;
591	  const setup = context.appliedSetup;
592	  const plate = context.plates.find((item) => item.active);
593	  const preset = context.printer.process.trim();
594	  const intent = context.setupIntent.trim();
595	  const ariaLabel = historical ? 'Earlier setup — saved with this conversation' : 'Current setup';
596	
597	  // Nothing vouches for this setup but the preset the person picked: no
598	  // agent is configured, or the host has no applied settings to report.
599	  const noAgent = !historical && !agentAvailable;
600	  if (noAgent || (!historical && !setup && !intent)) {
601	    const estimate = estimateView(context);
602	    return <section className="current-setup current-setup--live" data-testid="current-setup" aria-label={ariaLabel}>
603	      <div className="current-setup-header"><span className="current-setup-label">Preset fallback</span>
604	        {noAgent && <span className="current-setup-state">No agent</span>}</div>
605	      {preset && <h2 className="current-setup-title" title={preset}>{preset}</h2>}
606	      {noAgent ? <p className="current-setup-line">No agent configured · using the selected preset.</p>
607	        : estimate.metrics.length > 0 ? <Metrics estimate={estimate} />
608	        : <p className="current-setup-line">{estimate.description}</p>}
609	    </section>;
610	  }
611	
612	  const estimate = estimateView(context);
613	  const summary = appliedSummary(setup);
614	  const justChanged = historical ? [] : recentAgentChange(changes, now);
615	  const edited = historical || working || justChanged.length > 0 ? [] : handEdits(changes);
616	  // "Edited by you" needs a setup the agent had a hand in; without one a
617	  // hand edit is simply how the project was made.
618	  const agentManaged = !!intent || (changes ?? []).some((change) => change.actor === 'agent');
619	  const editedByYou = edited.length > 0 && agentManaged;
620	  // Out of date stands the card down: it drops the accent, as a saved card
621	  // does, because it no longer vouches for the numbers under it.
622	  const outOfDate = estimate.status === 'stale' && !working && justChanged.length === 0 && !editedByYou;
623	  const live = !historical && !outOfDate;
624	  const findings = [...deterministicAttention(context), ...attention];
625	
626	  // An out-of-date card is an earlier setup too: what it summarised has
627	  // been overtaken by the project, whichever chat it sits in.
628	  const label = sent ? 'Saved sliced snapshot' : historical || outOfDate ? 'Earlier setup' : 'Setup summary';
629	  const saved = formatMoment(savedAt);
630	  const state: ReactNode = historical
631	    ? sent ? 'Sliced & sent'
632	      : estimate.status === 'stale' ? 'Out of date'
633	      : saved ? <><span className="jp-icon jp-icon-clock" aria-hidden="true" />Saved {saved}</> : null
634	    : working ? 'Agent working'
635	    : justChanged.length > 0 ? 'Updated'
636	    : estimate.status === 'recomputing' ? 'Confirmed'
637	    : editedByYou ? 'Edited by you'
638	    : outOfDate ? 'Out of date'
639	    : estimate.status === 'none' && !estimate.sliced ? 'Not sliced'
640	    : 'Current';
641	
642	  const title = intent || preset;
643	  // A saved summary from before the card read applied settings has only
644	  // the preset differences it was saved with. Those are shown as what they
645	  // are; today's settings never stand in for them.
646	  const savedDifferences = !setup && context.presetDeltas.length > 0
647	    ? `Saved preset differences: ${context.presetDeltas.slice(0, 2).map((delta) =>
648	      `${delta.label || delta.key} ${delta.value}`).join(' · ')}` : '';
649	  const lines = summary.length > 0 ? summary
650	    : setup?.printableObjects === 0 ? ['No printable objects on this plate']
651	    : savedDifferences ? [savedDifferences]
652	    : [historical ? 'Applied settings were not saved with this chat' : 'Applied settings unavailable'];
653	
654	  // The estimate area. A hand edit that outdated the slice has no estimate
655	  // to offer for the settings now in force, and says so in one line.
656	  const withheld = editedByYou && estimate.status === 'stale';
657	  const heading = withheld ? ''
658	    : estimate.heading ? estimate.heading
659	    : estimate.metrics.length === 0 ? ''
660	    : sent ? 'Saved pre-slice estimates'
661	    : working ? 'Last confirmed estimates' : '';
662	  const description = withheld ? (estimate.plate ? `Estimate unavailable for these edits · ${estimate.plate}`
663	    : 'Estimate unavailable for these edits') : estimate.description;
664	  const canCompute = !historical && !working && !!onCompute && estimate.status === 'none';
665	
666	  const step = justChanged[justChanged.length - 1];
667	  // Orca's undo takes the top of its own stack. Only a project step the
668	  // agent just made is known to be there; a preset edit is not on it at all.
669	  const undoable = !!onUndo && !working && step?.kind === 'step' && context.history.canUndo;
670	  const after = plate?.estimate;
671	  const estimateDelta = justChanged.length > 0 && estimateBefore && after && estimate.status === 'current' &&
672	    (estimateBefore.printTimeSeconds !== after.printTimeSeconds || estimateBefore.materialGrams !== after.materialGrams)
673	    ? `Estimate: ${estimatePair(estimateBefore)} → ${estimatePair(after)}` : '';
674	  const named = edited.slice(0, 2).map((change) => `${change.label} ${change.to || 'none'}`);
675	  const editedText = edited.length > 2 ? `${named.join(', ')} and ${plural(edited.length - 2, 'more setting', 'more settings')}`
676	    : named.join(' and ');
677	
678	  return <section className={live ? 'current-setup current-setup--live' : 'current-setup'}
679	    data-testid="current-setup" aria-label={ariaLabel} aria-busy={working || undefined}>
680	    <div className="current-setup-header"><span className="current-setup-label">{label}</span>
681	      {state && <span className="current-setup-state">{state}</span>}</div>
682	    {title && <h2 className="current-setup-title" title={title}>{title}</h2>}
683	    {lines.map((line, index) => <p className="current-setup-line" key={index}>{line}</p>)}
684	    {heading && <p className="current-setup-heading">{heading}</p>}
685	    {!withheld && estimate.metrics.length > 0 && <Metrics estimate={estimate} />}
686	    {description && <p className="current-setup-line">{description}</p>}
687	    {sent && estimate.metrics.length > 0 && <p className="current-setup-line">Actual time &amp; material unavailable.</p>}
688	    {canCompute && <button type="button" className="current-setup-link" onClick={onCompute}>Compute estimates</button>}
689	    <hr className="current-setup-divider" />
690	    {working && <>
691	      <p className="current-setup-line">Agent is applying and evaluating changes…<br />
692	        Shown settings remain the last confirmed setup.</p>
693	      <hr className="current-setup-divider" />
694	    </>}
695	    {!working && justChanged.length > 0 && <>
696	      <p className="current-setup-line">{justChanged.map(changeText).join(' · ')}</p>
697	      {estimateDelta && <p className="current-setup-line">{estimateDelta}</p>}
698	      {undoable && <button type="button" className="current-setup-link" onClick={() => onUndo!(step.seq)}>Undo</button>}
699	      <hr className="current-setup-divider" />
700	    </>}
701	    {outOfDate && <>
702	      <div className="current-setup-attention">
703	        <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />
704	          {/* A saved card is about the project as it was saved, not today's. */}
705	          {historical ? 'These estimates were already out of date when saved.'
706	            : 'Estimates no longer match the current project.'}</p>
707	        {plate?.invalidatedBy && <p className="current-setup-line">{plate.invalidatedBy}</p>}
708	        {!historical && onCompute && <button type="button" className="current-setup-link" onClick={onCompute}>
709	          Refresh setup &amp; recompute</button>}
710	      </div>
711	      <hr className="current-setup-divider" />
712	    </>}
713	    {editedByYou && <>
714	      <p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
715	        <span>You set {editedText} outside the agent. Your current settings are preserved.</span></p>
716	      <hr className="current-setup-divider" />
717	    </>}
718	    <Attention findings={findings} />
719	    <button type="button" className="current-setup-disclosure" aria-expanded={expanded} onClick={onToggle}>
720	      <span className={`jp-icon jp-icon-chevron-${expanded ? 'down' : 'right'}`} aria-hidden="true" />Setup details
721	    </button>
722	    {expanded && <Details context={context} />}
723	    {historical && <>
724	      <hr className="current-setup-divider" />
725	      {sent && <p className="current-setup-sent">{[formatMoment(sent.at), sent.printer && `sent to ${sent.printer}`]
726	        .filter(Boolean).join(' · ')}</p>}
727	      <p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
728	        <span>{sent ? 'Saved snapshot.' : 'Saved with this chat.'} The canvas shows your current project.</span></p>
729	    </>}
730	  </section>;
731	}
