content.content:
  padding: 12px;
  background: var(--surface-canvas);
}

.current-setup {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  padding: 12px 16px;
  border-radius: var(--radius-container);
  background: var(--surface-subtle);
}

/* Drawn inside the box, as Figma's stroke is: the edge follows the corner
   radius and takes no width from the rows. */
.current-setup--live {
  box-shadow: inset 2px 0 0 var(--action-primary);
}

.current-setup p,
.current-setup h2,
.current-setup h3,
.current-setup dl,
.current-setup dd,
.current-setup ul {
  margin: 0;
}

/* Header in Metadata Bold: what the card is on the left, the one state it is
   in on the right. One line, always: the dock narrows with the window, and a
   wrapped header silently costs the thread a row. The label gives way. */
.current-setup-header {
  display: flex;
  align-items: center;
  gap: 8px;
  font: var(--font-metadata-bold);
  color: var(--text-secondary);
  white-space: nowrap;
}

.current-setup--live .current-setup-header {
  color: var(--action-primary);
}

.current-setup-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.current-setup-state {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
}

/* Body Bold, one line. The whole sentence is in the tooltip. */
.current-setup-title {
  font: var(--font-body-bold);
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.current-setup-line {
  font: var(--font-label);
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}

.current-setup-heading {
  font: var(--font-metadata-bold);
  color: var(--text-primary);
}

/* Time, material, plate. They wrap as whole clauses at a narrow dock. */
.current-setup-metrics {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 12px;
  font: var(--font-label-bold);
  color: var(--text-primary);
}

.current-setup-metric {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.current-setup-metric .jp-icon,
.current-setup-info .jp-icon,
.current-setup-state .jp-icon {
  color: var(--text-secondary);
}

/* The fact glyphs sit inside a row of text, so they take the card's own
   size; the disclosure chevrons stay on the icon scale. */
.current-setup-metric .jp-icon,
.current-setup-info .jp-icon,
.current-setup-state .jp-icon,
.current-setup-warning .jp-icon {
  width: var(--setup-card-icon-size);
  height: var(--setup-card-icon-size);
}

.current-setup-divider {
  flex: 0 0 auto;
  width: 100%;
  height: 1px;
  margin: 0;
  border: 0;
  background: var(--border-subtle);
}

.current-setup-attention {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}

.current-setup-warning {
  display: flex;
  align-items: center;
  gap: 8px;
  font: var(--font-metadata-bold);
  color: var(--text-primary);
}

/* Colour is never the only signal: the row always has its icon and words. */
.current-setup-warning .jp-icon {
  color: var(--status-warning);
}

.current-setup-info {
  display: flex;
  align-items: center;
  gap: 8px;
  font: var(--font-label);
  color: var(--text-secondary);
}

.current-setup-info > span:last-child {
  min-width: 0;
  overflow-wrap: anywhere;
}

/* The design system's Button/Link: text only, Label Bold, action/primary. */
.current-setup-link {
  align-self: flex-start;
  height: 26px;
  padding: 0 4px;
  border: 0;
  border-radius: var(--radius-standard);
  background: none;
  font: var(--font-label-bold);
  color: var(--action-primary);
  cursor: pointer;
}

.current-setup-link:hover {
  color: var(--action-primary-hover);
  text-decoration: underline;
}

.current-setup-link:active {
  color: var(--action-primary-pressed);
}

/* The design system's Disclosure header: one 28px target for the whole row. */
.current-setup-disclosure {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
