"""Builds the setup-card mockup from the repository's own token file and the
Agent page's own stylesheet, so no colour, radius, font or control size in it
is typed by hand. Prints a markdown table of the classes the mockup uses."""
import base64, json, re, subprocess, sys

W = '/Users/kenneth/Projects/JusPrin/.claude/worktrees/print-settings-display-a02cb1'
UI = W + '/src/slic3r/GUI/JusPrin'
OUT = sys.argv[1]
commit = subprocess.check_output(['git', '-C', W, 'rev-parse', '--short', 'HEAD']).decode().strip()
tokens = json.load(open(W + '/resources/jusprin/ui/design-tokens.json'))
css = open(UI + '/AgentUI/src/styles.css').read()

kebab = lambda name: re.sub(r'[A-Z]', lambda m: '-' + m.group(0).lower(), name)

# The same variables WebShared/tokens.ts and AgentUI/src/tokens.ts write.
static = {}
for name, value in tokens['dimension']['radius'].items():
    static[f'--radius-{kebab(name)}'] = f'{value}px'
ui = tokens['typography']['ui']
family = f"'{ui['family']}', {ui['cssFallback']}"
for name, role in tokens['typography']['roles'].items():
    static[f'--font-{kebab(name)}'] = f"{role['weight']} {role['size']}px/{role['lineHeight']}px {family}"
icon = tokens['component']['button']['icon']
