family = f"'{ui['family']}', {ui['cssFallback']}"
for name, role in tokens['typography']['roles'].items():
    static[f'--font-{kebab(name)}'] = f"{role['weight']} {role['size']}px/{role['lineHeight']}px {family}"
icon = tokens['component']['button']['icon']
static['--button-icon-icon-size'] = f"{icon['iconSize']}px"
static['--setup-card-icon-size'] = f"{tokens['component']['setupCard']['iconSize']}px"

def colours(mode):
    return {f'--{group}-{kebab(name)}': value for group, values in tokens['semantic'][mode].items()
            for name, value in values.items() if isinstance(value, str)}

block = lambda selector, variables: selector + ' {\n' + ''.join(f'  {k}: {v};\n' for k, v in variables.items()) + '}\n'

def data_uri(path, mime):
    return f"data:{mime};base64," + base64.b64encode(open(path, 'rb').read()).decode()

# The real stylesheet, self-contained: fonts and icon masks embedded.
css = re.sub(r"url\('\.\./\.\./WebShared/fonts/([^']+)'\)",
             lambda m: f"url('{data_uri(UI + '/WebShared/fonts/' + m.group(1), 'font/woff')}')", css)
css = re.sub(r"url\('@resources/([^']+\.svg)'\)",
             lambda m: f"url('{data_uri(W + '/resources/' + m.group(1), 'image/svg+xml')}')", css)
# The page's html/body rules size a full web view; the mockup shows frames.
