# Rules this design adds. Tokens and spacing-scale literals only.
new_css = '''
/* NEW 1. The setup page's scrolling body: .pinned-setup's own padding and
   surface, given the height the chat body had. */
.current-setup-page {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 12px;
