/* NEW 2. Which settings-tab page and group a run of rows belongs to. The
   same role and colour as .current-setup-sent. */
.current-setup-group {
  padding-top: 4px;
  font: var(--font-metadata-bold);
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}

/* NEW 3. A change row keeps to one line where it can: the setting's name
   gives way, and the value is never cut. The whole name is in the tooltip. */
.current-setup-row--change dt {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
