print('| Class | Font role | Colour tokens | Other tokens | New? |\n|---|---|---|---|---|')
for name in classes:
    fonts, colour, other = [], [], []
    for selector, body in rules:
        parts = [s.strip() for s in selector.split(',')]
        if not any(re.fullmatch(r'(\.current-setup(--live)? )?\.' + re.escape(name) + r'( (dt|dd|h1))?', p) or
