                (fonts if prop == 'font' else colour if prop in ('color', 'background', 'box-shadow', 'border-bottom') else other).append(var)
    uniq = lambda xs: ', '.join(f'`{x}`' for x in dict.fromkeys(xs)) or ' '
    print(f"| `.{name}` | {uniq(fonts)} | {uniq(colour)} | {uniq(other)} | {'new' if '.' + name + ' ' in new_css or '.' + name + '\\n' in new_css else ' '} |")

