1	// A compact, chat-owned account of the selected presets and every value that
2	// differs from them. Native code supplies facts and formatted values; this
3	// page only orders and presents them.
4	
5	import { ReactNode, useState } from 'react';
6	import { ChangeInfo, PresetDeltaInfo, SliceEstimateInfo, WorkspaceContext } from '../bridge/protocol';
7	
8	export interface SetupCardProps {
9	  context: WorkspaceContext | null;
10	  working?: boolean;
11	  historical?: boolean;
12	  savedAt?: string;
13	  agentAvailable?: boolean;
14	  changes?: ChangeInfo[];
15	  now?: number;
16	  estimateBefore?: SliceEstimateInfo | null;
17	  sent?: { at: string; printer: string };
18	  attention?: Finding[];
19	  onCompute?: () => void;
20	  onUndo?: (changeSeq: number) => void;
21	  onViewSetup?: () => void;
22	}
23	
24	export function formatPrintTime(seconds: number): string {
25	  const minutes = Math.round(seconds / 60);
26	  if (minutes < 60) return `~${minutes} min`;
27	  return `~${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
28	}
29	
30	export function formatGrams(grams: number): string {
31	  return `${grams < 10 ? Math.round(grams * 10) / 10 : Math.round(grams)} g`;
32	}
33	
34	export function formatCost(cost: number, currency: string): string {
35	  if (currency) {
36	    try {
37	      return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(cost);
38	    } catch {
39	      // An unknown regional code does not make the native amount disappear.
40	    }
41	  }
42	  return `cost ${cost.toFixed(2)}`;
43	}
44	
45	export function formatMoment(value: string | undefined): string {
46	  if (!value) return '';
47	  const date = new Date(value);
48	  if (Number.isNaN(date.getTime())) return value;
49	  return date.toLocaleString(undefined, {
50	    month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false,
51	  });
52	}
53	
54	export const RECENT_CHANGE_MS = 60000;
55	
56	export interface EstimateView {
57	  heading: string;
58	  metrics: { icon: string; text: string }[];
59	  cost: string;
60	  plate: string;
61	  description: string;
62	  status: 'current' | 'recomputing' | 'stale' | 'none';
63	  sliced: boolean;
64	}
65	
66	export function estimateView(context: WorkspaceContext): EstimateView {
67	  const plate = context.plates.find((item) => item.active);
68	  const view: EstimateView = {
69	    heading: '', metrics: [], cost: '', plate: plate?.name ?? '', description: '', status: 'none', sliced: !!plate?.sliced,
70	  };
71	  if (!plate) return { ...view, description: 'Estimate unavailable' };
72	  const estimate = plate.estimate;
73	  const scoped = (text: string) => plate.name ? `${text} · ${plate.name}` : text;
74	  const metrics: EstimateView['metrics'] = [];
75	  if (estimate && (estimate.timeAvailable ?? estimate.printTimeSeconds > 0))
76	    metrics.push({ icon: 'clock', text: formatPrintTime(estimate.printTimeSeconds) });
77	  if (estimate && (estimate.materialAvailable ?? estimate.materialGrams > 0))
78	    metrics.push({ icon: 'package', text: formatGrams(estimate.materialGrams) });
79	  if (plate.estimateStatus === 'recomputing')
80	    return { ...view, status: 'recomputing', heading: 'Time & material estimates recomputing…',
81	      description: scoped('Settings confirmed') };
82	  if (metrics.length === 0)
83	    return { ...view, description: scoped(plate.sliced ? 'Estimate unavailable' : 'Not sliced yet · estimates unavailable') };
84	  const cost = estimate && estimate.materialCost !== null && estimate.materialCost >= 0.005
85	    ? formatCost(estimate.materialCost, context.currency) : '';
86	  if (plate.estimateStatus === 'stale')
87	    return { ...view, status: 'stale', heading: 'Previous estimates · not current', metrics, cost };
88	  return { ...view, status: 'current', metrics, cost };
89	}
90	
91	export interface Finding { title: string; detail?: string; facts?: string[]; }
92	
93	export function deterministicAttention(context: WorkspaceContext): Finding[] {
94	  const review = context.printerReview;
95	  if (!review) return [];
96	  const priority: Record<string, number> = { filament: 0, nozzle: 1, model: 2, plate: 3 };
97	  const noun: Record<string, string> = { filament: 'material', nozzle: 'nozzle', model: 'printer', plate: 'build plate' };
98	  const when = formatMoment(review.observed?.observedAt);
99	  return [...review.mismatches].sort((a, b) => (priority[a.what] ?? 4) - (priority[b.what] ?? 4)).flatMap((mismatch) => {
100	    const thing = noun[mismatch.what] ?? 'printer setup';
101	    if (mismatch.source === 'device') {
102	      if (!when) return [];
103	      const facts = [`Setup: ${mismatch.configured}`, `Printer last reported: ${mismatch.observed}`, `Reported ${when}`];
104	      if (review.observed?.connection) facts.push(`Printer is ${review.observed.connection} now`);
105	      return [{ title: `Last reported ${thing} differs`,
106	        detail: `Setup uses ${mismatch.configured}. Printer last reported ${mismatch.observed}.`, facts }];
107	    }
108	    return [{ title: `Confirmed ${thing} differs`,
109	      detail: `Setup uses ${mismatch.configured}. You confirmed ${mismatch.observed}.`,
110	      facts: [`Setup: ${mismatch.configured}`, `You confirmed: ${mismatch.observed}`] }];
111	  });
112	}
113	
114	export function recentAgentChange(changes: ChangeInfo[] | undefined, now: number): ChangeInfo[] {
115	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
116	  const last = log.at(-1);
117	  if (!last || last.actor !== 'agent' || (last.kind !== 'setting' && last.kind !== 'step')) return [];
118	  const made = Date.parse(last.createdAt);
119	  if (!Number.isFinite(made) || now - made >= RECENT_CHANGE_MS || now < made) return [];
120	  let start = log.length - 1;
121	  while (start > 0 && log[start - 1].actor === 'agent' && log[start - 1].afterId === last.afterId &&
122	    (log[start - 1].kind === 'setting' || log[start - 1].kind === 'step')) start -= 1;
123	  return log.slice(start);
124	}
125	
126	export function handEdits(changes: ChangeInfo[] | undefined): ChangeInfo[] {
127	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
128	  let start = log.length;
129	  while (start > 0 && log[start - 1].actor === 'person' && log[start - 1].kind !== 'restore') start -= 1;
130	  const net = new Map<string, ChangeInfo>();
131	  for (const change of log.slice(start))
132	    if (change.kind === 'setting') net.set(change.key || change.label, change);
133	  return [...net.values()];
134	}
135	
136	function changeText(change: ChangeInfo): string {
137	  if (change.kind !== 'setting') return change.label || 'Object settings changed';
138	  return `${change.label} ${change.from || 'none'} → ${change.to || 'none'}`;
139	}
140	
141	function estimatePair(estimate: SliceEstimateInfo): string {
142	  return `${formatPrintTime(estimate.printTimeSeconds)} / ${formatGrams(estimate.materialGrams)}`;
143	}
144	
145	function plural(count: number, one: string, many: string): string {
146	  return `${count} ${count === 1 ? one : many}`;
147	}
148	
149	function shortPreset(name: string): string {
150	  const separator = name.indexOf(' @');
151	  return separator < 0 ? name : name.slice(0, separator);
152	}
153	
154	export function presetsLine(context: WorkspaceContext, title: string): string {
155	  const process = context.printer.process.trim();
156	  if (!process) return '';
157	  const filaments = context.setupIdentity?.filaments ?? [];
158	  const first = (filaments[0]?.preset || context.printer.filament).trim();
159	  const filament = first ? `${shortPreset(first)}${filaments.length > 1 ? ` +${filaments.length - 1}` : ''}` : '';
160	  const parts = title === process ? [filament] : [shortPreset(process), filament];
161	  return parts.filter(Boolean).join(' · ');
162	}
163	
164	export function orderedPresetDeltas(deltas: PresetDeltaInfo[], changes?: ChangeInfo[]): PresetDeltaInfo[] {
165	  const newest = new Map<string, number>();
166	  for (const change of changes ?? [])
167	    if (change.kind === 'setting' && change.key) newest.set(change.key, Math.max(newest.get(change.key) ?? 0, change.seq));
168	  return deltas.map((delta, index) => ({ delta, index })).sort((left, right) => {
169	    if (left.delta.origin !== right.delta.origin) return left.delta.origin === 'agent' ? -1 : 1;
170	    const leftSeq = newest.get(left.delta.key);
171	    const rightSeq = newest.get(right.delta.key);
172	    if (leftSeq !== undefined || rightSeq !== undefined) return (rightSeq ?? -1) - (leftSeq ?? -1);
173	    return left.index - right.index;
174	  }).map(({ delta }) => delta);
175	}
176	
177	export function overrideObjectCount(context: WorkspaceContext): number {
178	  return new Set((context.appliedSetup?.localOverrides ?? [])
179	    .map((local) => local.object).filter((object): object is number => object !== undefined)).size;
180	}
181	
182	export interface SetupPresentationOptions {
183	  historical?: boolean;
184	  working?: boolean;
185	  changes?: ChangeInfo[];
186	  now?: number;
187	  sent?: { at: string; printer: string };
188	  savedAt?: string;
189	}
190	
191	export function setupPresentation(context: WorkspaceContext, options: SetupPresentationOptions = {}) {
192	  const historical = !!options.historical;
193	  const working = !!options.working && !historical;
194	  const estimate = estimateView(context);
195	  const justChanged = historical ? [] : recentAgentChange(options.changes, options.now ?? Date.now());
196	  const edited = historical || working || justChanged.length > 0 ? [] : handEdits(options.changes);
197	  const agentManaged = !!context.setupIntent.trim() || (options.changes ?? []).some((change) => change.actor === 'agent');
198	  const editedByYou = edited.length > 0 && agentManaged;
199	  const outOfDate = estimate.status === 'stale' && !working && justChanged.length === 0 && !editedByYou;
200	  const saved = formatMoment(options.savedAt);
201	  const label = options.sent ? 'Saved sliced snapshot' : historical || outOfDate ? 'Earlier setup' : 'Setup summary';
202	  const state: ReactNode = historical
203	    ? options.sent ? 'Sliced & sent' : estimate.status === 'stale' ? 'Out of date'
204	      : saved ? <><span className="jp-icon jp-icon-clock" aria-hidden="true" />Saved {saved}</> : null
205	    : working ? 'Agent working' : justChanged.length > 0 ? 'Updated'
206	    : estimate.status === 'recomputing' ? 'Confirmed' : editedByYou ? 'Edited by you'
207	    : outOfDate ? 'Out of date' : estimate.status === 'none' && !estimate.sliced ? 'Not sliced' : 'Current';
208	  return { label, state, title: context.setupIntent.trim() || context.printer.process.trim(), estimate,
209	    justChanged, edited, editedByYou, outOfDate, live: !historical && !outOfDate };
210	}
211	
212	function Metrics({ estimate }: { estimate: EstimateView }) {
213	  return <div className="current-setup-metrics">
214	    {estimate.metrics.map((metric) => <span className="current-setup-metric" key={metric.icon}>
215	      <span className={`jp-icon jp-icon-${metric.icon}`} aria-hidden="true" />{metric.text}</span>)}
216	    {estimate.plate && <span className="current-setup-metric">
217	      <span className="jp-icon jp-icon-grid-3x3" aria-hidden="true" />{estimate.plate}</span>}
218	    {estimate.cost && <span className="current-setup-metric">{estimate.cost}</span>}
219	  </div>;
220	}
221	
222	function Attention({ findings }: { findings: Finding[] }) {
223	  const [open, setOpen] = useState(false);
224	  if (findings.length === 0) return null;
225	  const first = findings[0];
226	  const reviewable = findings.length > 1 || (first.facts ?? []).length > 0;
227	  const subject = findings.length > 1 ? plural(findings.length, 'finding', 'findings')
228	    : first.title.replace(/^(Last reported|Confirmed) | differs$/g, '');
229	  return <>
230	    <div className="current-setup-attention">
231	      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />{first.title}</p>
232	      {first.detail && <p className="current-setup-line">{first.detail}</p>}
233	      {reviewable && <button type="button" className="current-setup-link" aria-expanded={open} onClick={() => setOpen(!open)}>
234	        Review {subject}</button>}
235	      {open && <ul className="current-setup-findings">{findings.map((finding, index) => <li key={index}>
236	        {findings.length > 1 && <strong>{finding.title}</strong>}
237	        {(finding.facts ?? []).map((fact) => <span key={fact}>{fact}</span>)}
238	      </li>)}</ul>}
239	    </div>
240	    <hr className="current-setup-divider" />
241	  </>;
242	}
243	
244	function DeltaRows({ deltas }: { deltas: PresetDeltaInfo[] }) {
245	  return <dl className="current-setup-rows">{deltas.map((delta, index) => {
246	    const location = [delta.page, delta.group, delta.label].filter(Boolean).join(' · ');
247	    return <div className="current-setup-row current-setup-row--change" key={`${delta.presetType ?? ''}-${delta.key}-${index}`}>
248	      <dt title={location || delta.label || delta.key}>{delta.label || delta.key}</dt>
249	      <dd>{delta.display || `${delta.preset} → ${delta.value}`}</dd>
250	    </div>;
251	  })}</dl>;
252	}
253	
254	export function SetupCard({ context, working = false, historical = false, savedAt, agentAvailable = true,
255	  changes, now = Date.now(), estimateBefore, sent, attention = [], onCompute, onUndo, onViewSetup }: SetupCardProps) {
256	  if (!context) return null;
257	  const ariaLabel = historical ? 'Earlier setup — saved with this conversation' : 'Current setup';
258	  const preset = context.printer.process.trim();
259	  const presentation = setupPresentation(context, { historical, working, changes, now, sent, savedAt });
260	
261	  if (!historical && !agentAvailable) {
262	    return <section className="current-setup current-setup--live" data-testid="current-setup" aria-label={ariaLabel}>
263	      <div className="current-setup-header"><span className="current-setup-label">Preset fallback</span>
264	        <span className="current-setup-state">No agent</span></div>
265	      {preset && <h2 className="current-setup-title" title={preset}>{preset}</h2>}
266	      <p className="current-setup-line">No agent configured · using the selected preset.</p>
267	      {onViewSetup && <><hr className="current-setup-divider" />
268	        <button type="button" className="current-setup-link" onClick={onViewSetup}>View setup</button></>}
269	    </section>;
270	  }
271	
272	  const { estimate, justChanged, edited, editedByYou, outOfDate } = presentation;
273	  const ordered = orderedPresetDeltas(context.presetDeltas, changes);
274	  const shown = ordered.slice(0, 2);
275	  const remaining = ordered.length - shown.length;
276	  const objects = overrideObjectCount(context);
277	  const note = [remaining > 0 ? plural(remaining, 'more change', 'more changes') : '',
278	    objects > 0 ? plural(objects, 'object with overrides', 'objects with overrides') : ''].filter(Boolean).join(' · ');
279	  const presets = presetsLine(context, presentation.title);
280	
281	  const withheld = editedByYou && estimate.status === 'stale';
282	  const heading = withheld ? '' : estimate.heading ? estimate.heading : estimate.metrics.length === 0 ? ''
283	    : sent ? 'Saved pre-slice estimates' : working ? 'Last confirmed estimates' : '';
284	  const description = withheld ? (estimate.plate ? `Estimate unavailable for these edits · ${estimate.plate}`
285	    : 'Estimate unavailable for these edits') : estimate.description;
286	  const canCompute = !historical && !working && !!onCompute && estimate.status === 'none';
287	  const step = justChanged.at(-1);
288	  const undoable = !!onUndo && !working && step?.kind === 'step' && context.history.canUndo;
289	  const plate = context.plates.find((item) => item.active);
290	  const after = plate?.estimate;
291	  const estimateDelta = justChanged.length > 0 && estimateBefore && after && estimate.status === 'current' &&
292	    (estimateBefore.printTimeSeconds !== after.printTimeSeconds || estimateBefore.materialGrams !== after.materialGrams)
293	    ? `Estimate: ${estimatePair(estimateBefore)} → ${estimatePair(after)}` : '';
294	  const named = edited.slice(0, 2).map((change) => `${change.label} ${change.to || 'none'}`);
295	  const editedText = edited.length > 2 ? `${named.join(', ')} and ${plural(edited.length - 2, 'more setting', 'more settings')}`
296	    : named.join(' and ');
297	  const findings = [...deterministicAttention(context), ...attention];
298	
299	  return <section className={presentation.live ? 'current-setup current-setup--live' : 'current-setup'}
300	    data-testid="current-setup" aria-label={ariaLabel} aria-busy={working || undefined}>
301	    <div className="current-setup-header"><span className="current-setup-label">{presentation.label}</span>
302	      {presentation.state && <span className="current-setup-state">{presentation.state}</span>}</div>
303	    {presentation.title && <h2 className="current-setup-title" title={presentation.title}>{presentation.title}</h2>}
304	    {presets && <p className="current-setup-line" title={presets}>{presets}</p>}
305	    {shown.length > 0 ? <DeltaRows deltas={shown} /> : <p className="current-setup-line">No changes from presets</p>}
306	    {note && <p className="current-setup-note">{note}</p>}
307	    {heading && <p className="current-setup-heading">{heading}</p>}
308	    {!withheld && estimate.metrics.length > 0 && <Metrics estimate={estimate} />}
309	    {description && <p className="current-setup-line">{description}</p>}
310	    {sent && estimate.metrics.length > 0 && <p className="current-setup-line">Actual time &amp; material unavailable.</p>}
311	    {canCompute && <button type="button" className="current-setup-link" onClick={onCompute}>Compute estimates</button>}
312	    <hr className="current-setup-divider" />
313	    {working && <><p className="current-setup-line">Agent is applying and evaluating changes…<br />
314	      Shown settings remain the last confirmed setup.</p><hr className="current-setup-divider" /></>}
315	    {!working && justChanged.length > 0 && <>
316	      <p className="current-setup-line">{justChanged.map(changeText).join(' · ')}</p>
317	      {estimateDelta && <p className="current-setup-line">{estimateDelta}</p>}
318	      {undoable && <button type="button" className="current-setup-link" onClick={() => onUndo!(step!.seq)}>Undo</button>}
319	      <hr className="current-setup-divider" />
320	    </>}
321	    {outOfDate && <><div className="current-setup-attention">
322	      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />
323	        {historical ? 'These estimates were already out of date when saved.' : 'Estimates no longer match the current project.'}</p>
324	      {plate?.invalidatedBy && <p className="current-setup-line">{plate.invalidatedBy}</p>}
325	      {!historical && onCompute && <button type="button" className="current-setup-link" onClick={onCompute}>
326	        Refresh setup &amp; recompute</button>}
327	    </div><hr className="current-setup-divider" /></>}
328	    {editedByYou && <><p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
329	      <span>You set {editedText} outside the agent. Your current settings are preserved.</span></p>
330	      <hr className="current-setup-divider" /></>}
331	    <Attention findings={findings} />
332	    <button type="button" className="current-setup-link" onClick={onViewSetup}>View setup</button>
333	    {historical && <><hr className="current-setup-divider" />
334	      {sent && <p className="current-setup-sent">{[formatMoment(sent.at), sent.printer && `sent to ${sent.printer}`]
335	        .filter(Boolean).join(' · ')}</p>}
336	      <p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
337	        <span>{sent ? 'Saved snapshot.' : 'Saved with this chat.'} The canvas shows your current project.</span></p>
338	    </>}
339	  </section>;
340	}
