import { useState } from 'react';
import { AppliedSetupInfo, ChangeInfo, PresetDeltaInfo, SetupIdentityInfo, WorkspaceContext } from '../bridge/protocol';
import { formatGrams, formatPrintTime, orderedPresetDeltas, setupPresentation } from './SetupCard';

interface SetupPageProps {
  context: WorkspaceContext;
  historical?: boolean;
  working?: boolean;
  changes?: ChangeInfo[];
  now?: number;
  sent?: { at: string; printer: string };
  savedAt?: string;
}

type LocalOverride = AppliedSetupInfo['localOverrides'][number];

function Row({ label, value, title }: { label: string; value: string; title?: string }) {
  return <div className="current-setup-row current-setup-row--change">
    <dt title={title || label}>{label}</dt><dd>{value}</dd>
  </div>;
}

function sentence(value: string): string {
  const words = value.replace(/[_-]+/g, ' ').trim();
  return words ? words.charAt(0).toUpperCase() + words.slice(1) : '';
}

function shortTarget(target: string): string {
  const separator = target.indexOf(' / ');
  return separator < 0 ? target : target.slice(separator + 3);
}

function overrideValue(local: LocalOverride, identity: SetupIdentityInfo | null | undefined): string {
  // Orca stores an object's filament choice as a one-based slot. Keeping this
  // one documented exception makes the generic value useful without teaching
  // the native formatter about a setting key.
  if (local.key === 'extruder') {
    const slot = Number(local.value);
    const filament = Number.isInteger(slot) && slot > 0 ? identity?.filaments[slot - 1] : undefined;
    return filament ? `${slot} · ${filament.preset || filament.material}` : (local.display || local.value);
  }
  return local.display || local.value || 'Present';
}

function Presets({ context }: { context: WorkspaceContext }) {
  const identity = context.setupIdentity;
  return <section className="current-setup-section">
    <h3>Presets</h3>
    <dl className="current-setup-rows">
      {identity?.printer && <Row label="Printer" value={identity.printer} />}
      {context.printer.process && <Row label="Process" value={context.printer.process} />}
      {(identity?.filaments ?? []).map((filament, index) =>
        <Row key={index} label={`Filament ${index + 1}`} value={filament.preset || filament.material || 'Unavailable'} />)}
      {identity?.plateType && <Row label="Build plate" value={identity.plateType} />}
    </dl>
  </section>;
}

function groupDeltas(deltas: PresetDeltaInfo[]) {
  const presets = new Map<string, Map<string, PresetDeltaInfo[]>>();
  for (const delta of deltas) {
    const preset = delta.presetName || 'Preset';
    const location = [delta.page, delta.group].filter(Boolean).join(' · ');
    const groups = presets.get(preset) ?? new Map<string, PresetDeltaInfo[]>();
    groups.set(location, [...(groups.get(location) ?? []), delta]);
    presets.set(preset, groups);
  }
  return presets;
}

function PresetChanges({ deltas, changes }: { deltas: PresetDeltaInfo[]; changes?: ChangeInfo[] }) {
  const ordered = orderedPresetDeltas(deltas, changes);
  return <section className="current-setup-section">
    <h3>Changed from presets · {ordered.length}</h3>
    {ordered.length === 0 ? <p className="current-setup-note">No changes from presets</p>
      : [...groupDeltas(ordered)].map(([preset, groups]) => <div className="current-setup-object" key={preset}>
        <p className="current-setup-object-name">{preset}</p>
        {[...groups].map(([location, rows]) => <div key={location || 'ungrouped'}>
          {location && <p className="current-setup-group">{location}</p>}
          <dl className="current-setup-rows">{rows.map((delta, index) => <Row
            key={`${delta.key}-${index}`}
            label={delta.label || delta.key}
            title={[delta.page, delta.group, delta.label].filter(Boolean).join(' · ') || delta.label || delta.key}
            value={delta.display || `${delta.preset} → ${delta.value}`}
          />)}</dl>
        </div>)}
      </div>)}
  </section>;
}

function ObjectOverrides({ context }: { context: WorkspaceContext }) {
  const setup = context.appliedSetup;
  const names = setup?.objects ?? [];
  const locals = setup?.localOverrides ?? [];
  const first = names.findIndex((_, object) => locals.some((local) => local.object === object));
  const [open, setOpen] = useState<Set<number>>(() => new Set(first < 0 ? [] : [first]));
  const toggle = (object: number) => setOpen((before) => {
    const next = new Set(before);
    if (next.has(object)) next.delete(object); else next.add(object);
    return next;
  });

  return <section className="current-setup-section">
    <h3>Objects on {context.plates.find((plate) => plate.active)?.name || 'plate'} · {names.length}</h3>
    {names.map((name, object) => {
      const entries = locals.filter((local) => local.object === object);
      if (entries.length === 0) return <div className="current-setup-object" key={object}>
        <p className="current-setup-object-name">{name}</p>
        <p className="current-setup-note">Uses plate settings</p>
      </div>;
      const groups = new Map<string, LocalOverride[]>();
      for (const local of entries) {
        const heading = local.kind === 'object' ? 'Whole object' : `${shortTarget(local.target)} · ${local.kind}`;
        groups.set(heading, [...(groups.get(heading) ?? []), local]);
      }
      const expanded = open.has(object);
      return <div className="current-setup-object" key={object}>
        <button type="button" className="current-setup-disclosure" aria-expanded={expanded} onClick={() => toggle(object)}>
          <span className={`jp-icon jp-icon-chevron-${expanded ? 'down' : 'right'}`} aria-hidden="true" />
          {name} · {entries.length} {entries.length === 1 ? 'override' : 'overrides'}
        </button>
        {expanded && <div className="current-setup-object-rows">{[...groups].map(([heading, rows]) =>
          <div key={heading}><p className="current-setup-group">{heading}</p>
            <dl className="current-setup-rows">{rows.map((local, index) => <Row key={`${local.key}-${index}`}
              label={local.label || sentence(local.kind)} value={overrideValue(local, context.setupIdentity)} />)}</dl>
          </div>)}</div>}
      </div>;
    })}
  </section>;
}

function plateEstimate(context: WorkspaceContext, index: number): string {
  const plate = context.plates[index];
  if (!plate.sliced || !plate.estimate) return 'Not sliced';
  const values: string[] = [];
  if (plate.estimate.timeAvailable ?? plate.estimate.printTimeSeconds > 0) values.push(formatPrintTime(plate.estimate.printTimeSeconds));
  if (plate.estimate.materialAvailable ?? plate.estimate.materialGrams > 0) values.push(formatGrams(plate.estimate.materialGrams));
  return values.join(' · ') || 'Estimate unavailable';
}

function Plates({ context }: { context: WorkspaceContext }) {
  const active = context.plates.findIndex((plate) => plate.active);
  return <section className="current-setup-section">
    <h3>Plates</h3>
    <dl className="current-setup-rows">{context.plates.map((plate, index) => {
      const spiral = index === active && context.appliedSetup?.spiralMode;
      return <Row key={plate.id} label={`${plate.name}${plate.active ? ' · shown' : ''}`}
        value={`${plateEstimate(context, index)}${spiral ? ' · Spiral vase' : ''}`} />;
    })}</dl>
  </section>;
}

export function SetupPage({ context, historical, working, changes, now, sent, savedAt }: SetupPageProps) {
  const presentation = setupPresentation(context, { historical, working, changes, now, sent, savedAt });
  return <main className="current-setup-page" data-testid="current-setup-page">
    <section className={presentation.live ? 'current-setup current-setup--live' : 'current-setup'}>
      <div className="current-setup-header"><span className="current-setup-label">{presentation.label}</span>
        {presentation.state && <span className="current-setup-state">{presentation.state}</span>}</div>
      {presentation.title && <h2 className="current-setup-title" title={presentation.title}>{presentation.title}</h2>}
      <hr className="current-setup-divider" />
      <Presets context={context} />
      <hr className="current-setup-divider" />
      <PresetChanges deltas={context.presetDeltas} changes={changes} />
      <hr className="current-setup-divider" />
      <ObjectOverrides context={context} />
      <hr className="current-setup-divider" />
      <Plates context={context} />
    </section>
  </main>;
}

