import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it, vi } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { PresetDeltaInfo } from '../bridge/protocol';
import { renderVisualCase, setupVisualCases, setupWorkspace } from './SetupCard.visual-cases';
import { SetupCard } from './SetupCard';
import { SetupPage } from './SetupPage';

function visual(id: string) {
  const entry = setupVisualCases.find((item) => item.id === id);
  if (!entry) throw new Error(`Missing visual case ${id}`);
  const onViewSetup = vi.fn();
  render(renderVisualCase(entry, { onViewSetup }));
  return { onViewSetup };
}

describe('setup differences handoff', () => {
  it('A1 shows two newest agent differences and counts the rest and object overrides', async () => {
    const { onViewSetup } = visual('A1');
    const card = screen.getByTestId('current-setup');
    expect(card).toHaveTextContent('Stop the corners lifting');
    expect(card).toHaveTextContent('0.20mm Standard · Generic ABS +2');
    expect(card).toHaveTextContent('Brim width0 → 8 mm');
    expect(card).toHaveTextContent('Brim typeAuto → Outer brim only');
    expect(card).toHaveTextContent('3 more changes · 1 object with overrides');
    await userEvent.click(within(card).getByRole('button', { name: 'View setup' }));
    expect(onViewSetup).toHaveBeenCalledOnce();
  });

  it('A2 uses the process as title, shows filaments only, and has the honest empty state', () => {
    visual('A2');
    const card = screen.getByTestId('current-setup');
    expect(within(card).getByRole('heading')).toHaveTextContent('0.20mm Standard @MyKlipper');
    expect(card).toHaveTextContent('Generic ABS +2');
    expect(card).not.toHaveTextContent('0.20mm Standard · Generic ABS');
    expect(card).toHaveTextContent('No changes from presets');
    expect(card).toHaveTextContent('Not sliced yet · estimates unavailable · Plate 1');
  });

  it('B shows full presets, grouped differences, objects, and plates without a composer', () => {
    visual('B');
    const page = screen.getByTestId('current-setup-page');
    expect(page).toHaveTextContent('PrinterMyKlipper 0.4 nozzle');
    expect(page).toHaveTextContent('Process0.20mm Standard @MyKlipper');
    expect(page).toHaveTextContent('Filament 3Generic PLA @System');
    expect(page).toHaveTextContent('Changed from presets · 5');
    expect(page).toHaveTextContent('Others · Brim');
    expect(page).toHaveTextContent('3x3_cali_RL.stl · 2 overrides');
    expect(page).toHaveTextContent('bracket.stlUses plate settings');
    expect(page).toHaveTextContent('Plate 1 · shown~2h 18m · 41 g');
    expect(page).toHaveTextContent('Plate 2Not sliced');
    expect(screen.queryByRole('textbox')).toBeNull();
  });

  it('renders arbitrary setting identities generically on the page and card', () => {
    for (const seed of [7, 19, 43, 101]) {
      const context = setupWorkspace();
      const all = Array.from({ length: 37 }, (_, index): PresetDeltaInfo => ({
        key: `generated_${seed}_${index}`,
        label: `Generated setting ${seed}-${index}`,
        preset: `${index}`,
        value: `${index + 1}`,
        display: `${index} → ${index + 1}`,
        origin: index % 2 ? 'user' : 'agent',
        presetType: index % 3 === 0 ? 'process' : index % 3 === 1 ? 'filament' : 'printer',
        presetName: `Preset ${index % 3}`,
        page: `Page ${index % 4}`,
        group: `Group ${index % 5}`,
      }));
      const chosen = Array.from({ length: 5 }, (_, offset) => all[(seed + offset * 11) % all.length]);
      context.presetDeltas = chosen;
      const view = render(<SetupPage context={context} />);
      for (const setting of chosen) {
        expect(screen.getByText(setting.label)).toBeInTheDocument();
        expect(screen.getByText(setting.display!)).toBeInTheDocument();
      }
      view.unmount();
      const card = render(<SetupCard context={context} onViewSetup={() => {}} />);
      expect(screen.getByTestId('current-setup')).toHaveTextContent('3 more changes');
      card.unmount();
    }
  });

  it('contains no setting identity in production presentation code except the documented filament-slot exception', () => {
    const card = readFileSync(resolve(__dirname, 'SetupCard.tsx'), 'utf8');
    const page = readFileSync(resolve(__dirname, 'SetupPage.tsx'), 'utf8');
    const forbidden = ['layer_height', 'wall_loops', 'brim_width', 'sparse_infill_density', 'enable_support'];
    for (const key of forbidden) {
      expect(card).not.toContain(key);
      expect(page).not.toContain(key);
    }
    expect(page.match(/'extruder'/g)).toHaveLength(1);
  });

  it('keeps legacy saved summaries readable with raw values and no grouping metadata', () => {
    const context = setupWorkspace();
    context.presetDeltas = [{ key: 'legacy', label: 'Legacy setting', preset: 'old', value: 'new', origin: 'user' }];
    render(<SetupPage context={context} historical />);
    expect(screen.getByText('old → new')).toBeInTheDocument();
    expect(screen.getByText('Legacy setting')).toBeInTheDocument();
  });
});
