import { describe, expect, it, vi } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ChangeInfo } from '../bridge/protocol';
import {
  deterministicAttention, estimateView, formatCost, formatGrams, formatPrintTime,
  handEdits, orderedPresetDeltas, overrideObjectCount, presetsLine, recentAgentChange,
  SetupCard,
} from './SetupCard';
import { setupWorkspace } from './SetupCard.visual-cases';

describe('setup card helpers', () => {
  it('formats estimates without inventing unavailable quantities', () => {
    expect(formatPrintTime(59)).toBe('~1 min');
    expect(formatPrintTime(8280)).toBe('~2h 18m');
    expect(formatGrams(3.26)).toBe('3.3 g');
    expect(formatCost(2.5, 'USD')).toContain('2.50');
    const context = setupWorkspace();
    context.plates[0].estimate = { printTimeSeconds: 8280, materialGrams: 0, materialCost: null,
      timeAvailable: true, materialAvailable: false };
    expect(estimateView(context).metrics).toEqual([{ icon: 'clock', text: '~2h 18m' }]);
  });

  it('shortens system suffixes and counts additional filament slots', () => {
    const context = setupWorkspace();
    expect(presetsLine(context, context.setupIntent)).toBe('0.20mm Standard · Generic ABS +2');
    expect(presetsLine(context, context.printer.process)).toBe('Generic ABS +2');
  });

  it('puts agent changes first, newest matching change first, then preserves native order', () => {
    const context = setupWorkspace();
    const changes: ChangeInfo[] = [
      { seq: 1, createdAt: '2026-10-08T10:00:00Z', kind: 'setting', actor: 'agent', key: 'brim_type',
        label: 'Brim type', conversationId: 'c', afterId: 'm' },
      { seq: 2, createdAt: '2026-10-08T10:00:01Z', kind: 'setting', actor: 'agent', key: 'brim_width',
        label: 'Brim width', conversationId: 'c', afterId: 'm' },
    ];
    expect(orderedPresetDeltas(context.presetDeltas, changes).slice(0, 3).map((item) => item.key))
      .toEqual(['brim_width', 'brim_type', 'initial_layer_print_height']);
  });

  it('counts distinct objects with overrides', () => {
    const context = setupWorkspace();
    expect(overrideObjectCount(context)).toBe(1);
    context.appliedSetup!.localOverrides.push({ object: 1, target: 'bracket.stl', kind: 'object', key: 'x', value: '1' });
    expect(overrideObjectCount(context)).toBe(2);
  });

  it('keeps recent agent batches and latest hand edits separate', () => {
    const changes: ChangeInfo[] = [
      { seq: 1, createdAt: '2026-10-08T10:00:00Z', kind: 'setting', actor: 'agent', key: 'a', label: 'A', conversationId: 'c', afterId: 'm' },
      { seq: 2, createdAt: '2026-10-08T10:00:01Z', kind: 'setting', actor: 'agent', key: 'b', label: 'B', conversationId: 'c', afterId: 'm' },
    ];
    expect(recentAgentChange(changes, Date.parse('2026-10-08T10:00:10Z'))).toHaveLength(2);
    const person = [...changes, { seq: 3, createdAt: '2026-10-08T10:01:00Z', kind: 'setting' as const,
      actor: 'person' as const, key: 'a', label: 'A', to: '3', conversationId: 'c', afterId: '' }];
    expect(handEdits(person).map((item) => item.key)).toEqual(['a']);
  });

  it('turns confirmed printer mismatches into deterministic findings', () => {
    const context = setupWorkspace();
    context.printerReview = { mismatches: [
      { what: 'nozzle', configured: '0.4 mm', observed: '0.6 mm', source: 'user_confirmed' },
    ] };
    expect(deterministicAttention(context)[0].title).toBe('Confirmed nozzle differs');
  });
});

describe('setup card states', () => {
  it('shows the compact generic summary and opens the setup page', async () => {
    const onViewSetup = vi.fn();
    render(<SetupCard context={setupWorkspace()} onViewSetup={onViewSetup} />);
    const card = screen.getByTestId('current-setup');
    expect(card).toHaveTextContent('Brim width0 → 8 mm');
    expect(card).toHaveTextContent('3 more changes · 1 object with overrides');
    await userEvent.click(within(card).getByRole('button', { name: 'View setup' }));
    expect(onViewSetup).toHaveBeenCalledOnce();
  });

  it('shows a truthful no-differences state', () => {
    const context = setupWorkspace();
    context.presetDeltas = [];
    render(<SetupCard context={context} onViewSetup={() => {}} />);
    expect(screen.getByTestId('current-setup')).toHaveTextContent('No changes from presets');
  });

  it('keeps no-agent fallback useful', () => {
    render(<SetupCard context={setupWorkspace()} agentAvailable={false} onViewSetup={() => {}} />);
    expect(screen.getByTestId('current-setup')).toHaveTextContent('No agent configured · using the selected preset.');
    expect(screen.getByRole('button', { name: 'View setup' })).toBeInTheDocument();
  });
});

