    const context = setupWorkspace();
    context.presetDeltas = [];
    render(<SetupCard context={context} onViewSetup={() => {}} />);
    expect(screen.getByTestId('current-setup')).toHaveTextContent('No changes from presets');
  });

  it('keeps no-agent fallback useful', () => {
    render(<SetupCard context={setupWorkspace()} agentAvailable={false} onViewSetup={() => {}} />);
    expect(screen.getByTestId('current-setup')).toHaveTextContent('No agent configured · using the selected preset.');
    expect(screen.getByRole('button', { name: 'View setup' })).toBeInTheDocument();
  });
});

