  return <>
    {name && <p className="current-setup-object-name">{name}</p>}
    {runs(deltas, (delta) => [delta.page, delta.group].filter(Boolean).join(' · ')).map(([location, rows]) =>
      <Group key={location} heading={location}><ChangeRows deltas={rows} /></Group>)}
  </>;
}

