        const valued = rows.filter((local) => local.label && (local.display || local.value));
        return <Group key={heading} heading={heading}>
          {valued.length > 0 && <dl className="current-setup-rows">{valued.map((local, index) =>
            <div className="current-setup-row current-setup-row--change" key={`${local.key}-${index}`}>
              <dt title={local.label}>{local.label}</dt><dd>{overrideValue(local, identity)}</dd>
            </div>)}</dl>}
        </Group>;
      })}
    </div>}
  </>;
