import { ChangeInfo, PresetDeltaInfo, WorkspaceContext } from '../bridge/protocol';
import { SetupCard, SetupCardProps } from './SetupCard';
import { SetupPage } from './SetupPage';

export interface SetupVisualCase {
  id: string;
  name: string;
  kind: 'card' | 'page';
  context: WorkspaceContext;
  props?: Omit<SetupCardProps, 'context'>;
}

const delta = (key: string, label: string, display: string, extra: Partial<PresetDeltaInfo> = {}): PresetDeltaInfo => ({
  key, label, display, preset: 'before', value: 'after', origin: 'agent', presetType: 'process',
  presetName: '0.20mm Standard @MyKlipper', page: 'Others', group: 'Brim', ...extra,
});

export function setupWorkspace(): WorkspaceContext {
  return {
    sessionId: 'visual-project', revision: 4, projectName: 'Workshop bracket', projectDirty: false,
    printer: { preset: 'MyKlipper 0.4 nozzle', filament: 'Generic ABS @System', process: '0.20mm Standard @MyKlipper' },
    plates: [
      { id: 'plate-1', name: 'Plate 1', active: true, sliced: true,
        estimate: { printTimeSeconds: 8280, materialGrams: 41, materialCost: null,
          timeAvailable: true, materialAvailable: true },
        estimateStatus: 'current', invalidatedBy: '', objects: [
          { id: 'bracket', name: '3x3_cali_RL.stl', instances: 1, selected: false },
          { id: 'cover', name: 'bracket.stl', instances: 1, selected: false },
        ] },
      { id: 'plate-2', name: 'Plate 2', active: false, sliced: false, estimate: null,
        estimateStatus: 'current', invalidatedBy: '', objects: [] },
    ],
    selection: { status: 'none', objectIds: [] }, history: { canUndo: true, canRedo: false },
    presetDeltas: [
      delta('brim_width', 'Brim width', '0 → 8 mm'),
      delta('brim_type', 'Brim type', 'Auto → Outer brim only'),
      delta('initial_layer_print_height', 'First layer height', '0.2 → 0.28 mm', { page: 'Quality', group: 'Layer height' }),
      delta('initial_layer_speed', 'First layer', '50 → 25 mm/s', { page: 'Speed', group: 'First layer speed', origin: 'user' }),
      delta('bed_temperature', 'Bed temperature', '100 → 105 ℃', { presetType: 'filament',
        presetName: 'Generic ABS @System', page: 'Filament', group: 'Bed temperature', origin: 'user' }),
    ],
    appliedSetup: { version: 1, plateId: 'plate-1', printableObjects: 2, spiralMode: false,
      variableLayerHeight: false, objects: ['3x3_cali_RL.stl', 'bracket.stl'], localOverrides: [
        { object: 0, target: '3x3_cali_RL.stl', kind: 'object', key: 'sparse_infill_density', value: '30%',
          label: 'Sparse infill density', display: '30%' },
        { object: 0, target: '3x3_cali_RL.stl / Corner tab', kind: 'modifier', key: 'wall_loops', value: '5',
          label: 'Wall loops', display: '5' },
      ] },
    setupIdentity: { printer: 'MyKlipper 0.4 nozzle', nozzles: [0.4], plateType: 'Smooth High Temp Plate', filaments: [
      { preset: 'Generic ABS @System', material: 'ABS' }, { preset: 'Generic PLA @System', material: 'PLA' },
      { preset: 'Generic PLA @System', material: 'PLA' },
    ] },
    printerReview: { mismatches: [] }, currency: '', setupIntent: 'Stop the corners lifting',
  };
}

const noChanges = structuredClone(setupWorkspace());
noChanges.setupIntent = '';
noChanges.presetDeltas = [];
noChanges.appliedSetup!.localOverrides = [];
noChanges.appliedSetup!.objects = [];
noChanges.appliedSetup!.printableObjects = 0;
noChanges.plates[0].sliced = false;
noChanges.plates[0].estimate = null;

const long = structuredClone(setupWorkspace());
long.setupIntent = 'Keep the corners of this unusually long workshop fixture flat through the entire print';
long.setupIdentity!.filaments = Array.from({ length: 6 }, (_, index) => ({ preset: `Material ${index + 1}`, material: 'PLA' }));
long.presetDeltas = Array.from({ length: 20 }, (_, index) => delta(`random_${index}`, `A deliberately long setting label ${index + 1}`,
  `${index} → ${index + 1} mm`, { page: `Page ${Math.floor(index / 5) + 1}`, group: `Group ${index % 5}` }));

export const visualChanges: ChangeInfo[] = [
  { seq: 1, createdAt: '2026-10-08T10:00:00', kind: 'setting', actor: 'agent', key: 'brim_type',
    label: 'Brim type', from: 'auto', to: 'outer', conversationId: 'visual', afterId: 'message-1' },
  { seq: 2, createdAt: '2026-10-08T10:01:00', kind: 'setting', actor: 'agent', key: 'brim_width',
    label: 'Brim width', from: '0', to: '8', conversationId: 'visual', afterId: 'message-1' },
];

export const setupVisualCases: SetupVisualCase[] = [
  { id: 'A1', name: 'Card · changes', kind: 'card', context: setupWorkspace(), props: { changes: visualChanges } },
  { id: 'A2', name: 'Card · no changes', kind: 'card', context: noChanges },
  { id: 'B', name: 'Setup page', kind: 'page', context: setupWorkspace(), props: { changes: visualChanges } },
  { id: 'stress-card', name: 'Card · long and dense', kind: 'card', context: long },
  { id: 'stress-page', name: 'Page · long and dense', kind: 'page', context: long },
];

export function renderVisualCase(entry: SetupVisualCase, handlers: { onViewSetup?: () => void } = {}) {
  if (entry.kind === 'page')
    return <SetupPage context={entry.context} changes={entry.props?.changes} />;
  return <SetupCard context={entry.context} {...entry.props} onViewSetup={handlers.onViewSetup ?? (() => {})} />;
}

